cd /exercise && node - <<'NODE'
const fs = require('fs');
const assert = require('assert');

const source = fs
  .readFileSync('sum-of-multiples.js', 'utf8')
  .replace(/^export\s+const\s+sum\s*=/m, 'const sum =');
const tempModule = '/tmp/sum-of-multiples-check.cjs';
fs.writeFileSync(tempModule, `${source}\nmodule.exports = { sum };\n`);

const { sum } = require(tempModule);

const cases = [
  { args: [[3, 5], 20], expected: 78, label: 'prompt example' },
  { args: [[3, 3, 5], 20], expected: 78, label: 'duplicate factors' },
  { args: [[3], 3], expected: 0, label: 'limit is exclusive' },
  { args: [[3], 4], expected: 3, label: 'first multiple below limit' },
  { args: [[], 10000], expected: 0, label: 'empty factors' },
  { args: [[0], 1], expected: 0, label: 'zero factor only' },
  { args: [[3, 0], 4], expected: 3, label: 'zero ignored with positive factor' },
  { args: [[-3, 5], 10], expected: 5, label: 'negative factor ignored' },
  { args: [[1], 10], expected: 45, label: 'factor one' },
  { args: [[2, 4, 8], 10], expected: 20, label: 'nested factors deduplicated' },
  { args: [], expected: 0, label: 'default arguments' },
];

for (const { args, expected, label } of cases) {
  assert.strictEqual(sum(...args), expected, `${label}: expected ${expected}`);
}

console.log(`Edge-case checks passed: ${cases.length}`);
NODE
